query GetTasksWithoutProject {
  tasksWithoutProject {
    taskId
    description
    status
    referenceFiles
    createdAt
    updatedAt
    root {
      ...TaskRootFields
      __typename
    }
    __typename
  }
}

fragment TaskRootFields on TaskRoot {
  kind
  recipientAddress
  ingressAgentRunId
  teamRunId
  hostRoot {
    kind
    runId
    __typename
  }
  start
  startError {
    code
    message
    __typename
  }
  closed
  status
  __typename
}

query GetProjects {
  projects {
    ...ProjectFields
    __typename
  }
}

fragment ProjectFields on Project {
  projectId
  name
  description
  createdAt
  updatedAt
  workspaces {
    workspaceId
    workspaceRootPath
    displayName
    description
    addedAt
    availability
    __typename
  }
  taskCount
  openTaskCount
  __typename
}

